import pandas as pd,numpy as np,glob
from scipy.optimize import least_squares
def load(f): return pd.read_csv(f).iloc[::5].reset_index(drop=True)
tr=[load(f) for f in glob.glob('train/*.csv')];va=[load(f) for f in glob.glob('val/*.csv')]
def sim(p,d):
    a,c,b,T,kw,Tw=p;dt=0.005
    V=d.voltage_pu.values-d.voltage_pu[0];th=d.bus_angle_rad.values;Vs=d.voltage_setpoint_pu.values-d.voltage_setpoint_pu[0]
    xf=th[0];x=0;P=[];Q=[]
    for i in range(len(d)):
        w=(th[i]-xf)/Tw;xf+=dt*w
        x+=dt*(c*V[i]+b*Vs[i]-x)/T
        P.append(-kw*w);Q.append(a*V[i]+x)
    return np.array(P),np.array(Q)
def res(p,ds):
    r=[]
    for d in ds:
        P,Q=sim(p,d);r+=[P-(d.active_power_pu-d.active_power_pu[0]),Q-(d.reactive_power_pu-d.reactive_power_pu[0])]
    return np.concatenate(r)
s=least_squares(res,[1,0,1,.5,.045,.05],args=(tr,),bounds=([-20,-50,-20,.02,0,.005],[20,50,20,10,1,2]))
